const $=id=>document.getElementById(id);
const [id,token]=location.hash.slice(1).split(':');
async function api(action='',method='GET'){const r=await fetch('/api/orders/'+encodeURIComponent(id)+(action?'/'+action:''),{method,headers:{'X-Order-Token':token||''}});const b=await r.json();if(!r.ok)throw Error(b.error);return b;}
async function load(){try{const o=await api();$('details').replaceChildren();for(const text of ['Order: '+o.id,'Customer: '+o.name,'Items: '+JSON.parse(o.items).map(p=>p.quantity+' × '+({egg:'Single eggs',half:'Half crate',crate:'Full crate'}[p.id])).join(', '),'Status: '+o.status,'Total: '+(o.amount===null?'Awaiting seller confirmation':new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN'}).format(o.amount/100)),'Payment: '+o.payment_status]){const p=document.createElement('p');p.textContent=text;$('details').append(p);} $('pay').hidden=!(o.status==='confirmed'&&o.amount&&o.payment_status!=='paid'&&o.payments_enabled);$('verify').hidden=!o.payment_reference||o.payment_status==='paid';$('whatsapp').hidden=false;$('whatsapp').href='https://wa.me/2348028091950?text='+encodeURIComponent('Hello, please confirm my egg order '+o.id+'. My private order link: '+location.origin+'/order.html#'+id+':'+token);}catch(e){$('message').textContent=e.message;}}
$('refresh').onclick=load;
$('pay').onclick=async()=>{$('pay').disabled=true;try{const b=await api('pay','POST');if(b.verify){$('message').textContent='Payment found. Tap Check payment to confirm.';}else location.assign(b.url);}catch(e){$('message').textContent=e.message;}finally{$('pay').disabled=false;await load();}};
$('verify').onclick=async()=>{try{const b=await api('verify','POST');$('message').textContent=b.paid?'Payment confirmed. Thank you!':'Payment has not been confirmed yet. Please check again later.';await load();}catch(e){$('message').textContent=e.message;}};
load();
